// bridges/a2a-mcp-bridge.ts
class A2AMCPBridge {
  // A2A Agent usando MCP Tools
  async delegateToMCPAgent(a2aTask: Task): Promise<TaskResult> {
    const mcpTools = await this.mcpClient.getTools();
    const relevantTool = this.selectToolForTask(a2aTask, mcpTools);

    const mcpResult = await this.mcpClient.invokeTool(
      relevantTool.name, 
      a2aTask.parameters
    );

    return this.convertMCPResultToA2A(mcpResult);
  }

  // MCP Server expondo A2A capabilities
  async exposeA2AAgentAsMCPTool(agent: A2AAgent): Promise<MCPTool> {
    return {
      name: agent.name,
      description: agent.description,
      inputSchema: agent.inputSchema,
      implementation: (params) => this.delegateToA2AAgent(agent, params)
    };
  }
}
